const $=s=>document.getElementById(s);let printing=false,last='',selected=localStorage.getItem('yonsei-printer')||'';
const savedScale=Number(localStorage.getItem('yonsei-print-scale')||94);$('scale').value=Number.isInteger(savedScale)&&savedScale>=85&&savedScale<=100?savedScale:94;
$('scale').onchange=()=>{if($('scale').checkValidity())localStorage.setItem('yonsei-print-scale',$('scale').value);};
let accessKey=sessionStorage.getItem('yonsei-cloud-print-key')||'';
const localBase='http://127.0.0.1:4178';
$('pair').onclick=()=>{try{const u=new URL($('pair-code').value.trim());if(!/^[a-f0-9]{48}$/.test(u.hash.slice(1)))throw Error();accessKey=u.hash.slice(1);sessionStorage.setItem('yonsei-cloud-print-key',accessKey);$('pair-code').value='';last='';refresh();}catch{$('status').textContent='로컬 관리 화면에서 복사한 연결 코드 전체를 입력해 주세요.';}};
$('disconnect').onclick=()=>{accessKey='';sessionStorage.removeItem('yonsei-cloud-print-key');$('jobs').replaceChildren();$('connection').value='';$('status').textContent='연결을 해제했습니다.';};
async function api(path,options={}){if(!accessKey)throw Error('위에서 Mac 연결 코드를 입력해 주세요.');const r=await fetch(localBase+path,{...options,headers:{'Content-Type':'application/json','X-Yonsei-Admin':'1','Authorization':'Bearer '+accessKey,...options.headers}});const d=await r.json();if(!r.ok)throw Error(d.error);return d;}
const rotations=new Map();
const labels={waiting:'인쇄 대기',sending:'프린터로 전송 중',submitted:'인쇄 대기열 전송 완료',uncertain:'인쇄 센터 확인 필요'};
async function refresh(){try{const d=await api('/admin/state');$('connection').value=d.connection;
 const old=$('printer').value||selected;$('printer').replaceChildren(...d.printers.map(p=>new Option(p.name+(p.uri.startsWith('ippusb:')?' · USB':' · 네트워크'),p.name)));if(d.printers.some(p=>p.name===old))$('printer').value=old;
 const key=JSON.stringify(d.jobs);if(key!==last&&!printing&&!$('jobs').contains(document.activeElement)){last=key;$('jobs').replaceChildren();if(!d.jobs.length)$('jobs').textContent='iPad에서 전송한 사진이 여기에 표시됩니다.';
 for(const j of d.jobs){const article=document.createElement('article');article.className='job';const img=new Image();fetch(localBase+`/admin/jobs/${j.id}/image`,{headers:{Authorization:'Bearer '+accessKey}}).then(r=>{if(!r.ok)throw Error();return r.blob();}).then(b=>{const u=URL.createObjectURL(b);img.addEventListener('load',()=>URL.revokeObjectURL(u),{once:true});img.src=u;}).catch(()=>{img.alt='사진을 불러오지 못했습니다.';});img.alt='인쇄할 완성 사진';const section=document.createElement('section');const title=document.createElement('h2');title.textContent=labels[j.state];const date=document.createElement('p');date.textContent=new Date(j.createdAt).toLocaleString('ko-KR')+' · '+j.id.slice(0,8);section.append(title,date);
 if(['waiting','submitted','uncertain'].includes(j.state)){const label=document.createElement('label');label.textContent='출력 매수';const count=document.createElement('input');count.type='number';count.min=1;count.max=10;count.value=1;label.append(count,document.createTextNode('장'));const print=document.createElement('button');print.className='print';print.textContent=j.state==='waiting'?'인쇄':'다시 인쇄';print.onclick=async()=>{if(printing)return;if(j.state==='uncertain'&&!confirm('이전 요청이 이미 출력됐을 수 있습니다. 인쇄 센터를 확인하셨다면 다시 인쇄해 주세요.'))return;printing=true;print.disabled=true;try{await api(`/admin/jobs/${j.id}/print`,{method:'POST',body:JSON.stringify({printer:$('printer').value,copies:Number(count.value),scale:Number($('scale').value),rotation:rotations.get(j.id)??j.rotation??0,reprint:j.state!=='waiting',expectedAttempt:j.attempt||0})});$('status').textContent='';}catch(e){$('status').textContent=e.message;}finally{printing=false;last='';document.activeElement?.blur();await refresh();}};const turn=document.createElement('button');turn.className='rotate';turn.type='button';const angle=()=>rotations.get(j.id)??j.rotation??0;const preview=document.createElement('canvas');preview.className='rotated-preview';preview.hidden=true;img.after(preview);const updateRotation=()=>{turn.textContent=angle()===90?'원본 방향으로':'세로로 90° 회전';if(!img.naturalWidth)return;const rotated=angle()===90;preview.hidden=!rotated;img.hidden=rotated;if(rotated){preview.width=img.naturalHeight;preview.height=img.naturalWidth;const c=preview.getContext('2d');c.translate(preview.width,0);c.rotate(Math.PI/2);c.drawImage(img,0,0);}turn.hidden=img.naturalWidth<=img.naturalHeight&&angle()===0;};img.onload=updateRotation;turn.onclick=()=>{rotations.set(j.id,angle()===90?0:90);updateRotation();};updateRotation();section.append(label,print,turn);section._preview=preview;}
 if(j.state!=='waiting'){const state=document.createElement('p');state.textContent=`최근 요청: ${j.copies}장 · ${j.scale||100}% · ${j.error||j.cupsJob||'전송 중'}`;section.append(state);}
 const del=document.createElement('button');del.className='delete';del.textContent='이 사진 삭제';del.disabled=j.state==='sending';del.onclick=async()=>{if(!confirm('Mac의 이 사진을 삭제할까요? 이미 보낸 인쇄 작업은 취소되지 않습니다.'))return;try{await api(`/admin/jobs/${j.id}`,{method:'DELETE'});last='';await refresh();}catch(e){$('status').textContent=e.message;}};section.append(del);const picture=document.createElement('div');picture.append(img);if(section._preview)picture.append(section._preview);article.append(picture,section);$('jobs').append(article);}}
 }catch(e){$('status').textContent='Mac 인쇄 도우미 연결을 확인해 주세요. '+e.message;}}
$('printer').onchange=()=>{selected=$('printer').value;localStorage.setItem('yonsei-printer',selected);};$('refresh').onclick=refresh;$('center').onclick=()=>alert('시스템 설정 → 프린터 및 스캐너 → CP1500 → 프린터 대기열에서 실제 작업 상태를 확인하세요.');$('copy').onclick=async()=>{try{await navigator.clipboard.writeText($('connection').value);$('copy').textContent='복사됨';}catch{$('connection').select();}};refresh();setInterval(refresh,2500);
